// kernel.ts — the entire plugin system, in one Map.
//
// The idea: construction binds to a NAME, not a class. Code that needs a Tab
// asks the kernel for whatever is registered under 'Tab' and constructs that.
// A plugin re-registers the name with an EXTENDED class — and every future
// construction produces the extension, with `super` chains, reactive state
// and methods all intact, because ivue inheritance is native inheritance.
//
// No DI container, no decorators, no tokens, no reflection metadata. A
// registry is a Map; late binding is a lookup at construction time. This is
// the whole thing.

type AnyClass = abstract new (...args: any[]) => any;

class Kernel {
  #classes = new Map<string, AnyClass>();

  /** Register (or replace) the class a name resolves to. */
  set<T extends AnyClass>(name: string, cls: T) {
    this.#classes.set(name, cls);
  }

  /** The class currently registered under `name`, or the fallback base. */
  get<T extends AnyClass>(name: string, base: T): T {
    return (this.#classes.get(name) as T) ?? base;
  }

  /** Forget every registration — back to the base classes. */
  clear() {
    this.#classes.clear();
  }
}

export const kernel = new Kernel();

// Tab.ts — an app class the kernel can swap. This file is "the app": it
// knows nothing about any plugin. It exposes a base class and a make()
// convention that constructs THROUGH the kernel by name.
import { ref } from 'vue';
import { Reactive, type ReactiveInstance } from '../../ivue';
import { kernel } from './kernel';

export class $Tab {
  constructor(public title: string) {}

  // reactive state — a ref-getter, materialized on first touch
  get closed() {
    return ref(false);
  }

  // DERIVED — plugins override these to change what a tab shows and does.
  // Plain getters: zero bytes, reactive via leaf tracking, super-chainable.
  get badges(): string[] {
    return [];
  }
  get accent(): string {
    return '#6366f1';
  }

  close() {
    this.closed.value = true;
  }
}

export type TabInstance = ReactiveInstance<$Tab>;

/**
 * The make convention: resolve the class registered under 'Tab' (or the base
 * if no plugin touched it), wrap it with Reactive() — idempotent, so already
 * transformed ancestors are skipped — and construct. Every call site in the
 * app uses makeTab(); none of them names a concrete class.
 */
export function makeTab(title: string): TabInstance {
  const TabClass = Reactive(kernel.get('Tab', $Tab));
  return new TabClass(title) as TabInstance;
}

// plugins.ts — third-party code. A plugin is a function that EXTENDS whatever
// class it's handed and returns the subclass. Because each plugin extends the
// current class, plugins STACK: apply timestamp then priority and a tab gets
// both, each level chaining through `super`.
//
// A plugin author never edits Tab.ts — they extend $Tab (or whatever the
// previous plugin produced) and let the kernel route construction to them.
import { ref } from 'vue';
import { $Tab } from './Tab';

export type TabPlugin = (Base: typeof $Tab) => typeof $Tab;

/** Adds an opened-at timestamp and a badge showing it. */
export const timestampPlugin: TabPlugin = (Base) =>
  class extends Base {
    get openedAt() {
      return ref(new Date().toLocaleTimeString());
    }
    get badges(): string[] {
      return [...super.badges, `opened ${this.openedAt.value}`];
    }
  };

/** Flags the tab as priority — prepends a badge and repaints the accent. */
export const priorityPlugin: TabPlugin = (Base) =>
  class extends Base {
    get badges(): string[] {
      return ['priority', ...super.badges];
    }
    get accent(): string {
      return '#f59e0b'; // overrides the base accent — behavior, not just data
    }
  };

// KernelExample.ts — the demo view-model, in ivue. It toggles plugins,
// rebuilds the kernel registration from the base + active plugins, and
// constructs tabs through makeTab() so new tabs pick up whatever is live.
import { ref, shallowRef } from 'vue';
import { Reactive } from '../../ivue';
import { kernel } from './kernel';
import { $Tab, makeTab, type TabInstance } from './Tab';
import { timestampPlugin, priorityPlugin, type TabPlugin } from './plugins';

interface PluginEntry {
  id: string;
  label: string;
  apply: TabPlugin;
}

class $KernelExample {
  #counter = 0;

  constructor() {
    // The kernel is a module singleton — a previous visit may have left a
    // registration. Rebuild from the current (empty) plugin set so this
    // route always starts on the base class.
    this.rebuildRegistration();
    this.addTab();
  }

  get tabs() {
    return shallowRef<TabInstance[]>([]);
  }
  get active() {
    return ref<Record<string, boolean>>({ timestamp: false, priority: false });
  }

  // CONSTANTS — the available plugins; plain field, never mutated.
  plugins: PluginEntry[] = [
    { id: 'timestamp', label: 'Timestamp plugin', apply: timestampPlugin },
    { id: 'priority', label: 'Priority plugin', apply: priorityPlugin },
  ];

  // DERIVED — plain getters.
  get activeLabels(): string[] {
    return this.plugins
      .filter((plugin) => this.active.value[plugin.id])
      .map((plugin) => plugin.label);
  }
  get activeSummary(): string {
    return this.activeLabels.length
      ? this.activeLabels.join(' + ')
      : 'the base class only';
  }
  get hasTabs(): boolean {
    return this.tabs.value.length > 0;
  }

  /** Compose the active plugins over the base and register the result. */
  rebuildRegistration() {
    let TabClass: typeof $Tab = $Tab;
    for (const plugin of this.plugins) {
      if (this.active.value[plugin.id]) TabClass = plugin.apply(TabClass);
    }
    kernel.set('Tab', TabClass);
  }

  togglePlugin(id: string) {
    this.active.value = { ...this.active.value, [id]: !this.active.value[id] };
    this.rebuildRegistration();
  }

  isActive(id: string): boolean {
    return !!this.active.value[id];
  }

  addTab() {
    this.tabs.value = [...this.tabs.value, makeTab(`Tab ${++this.#counter}`)];
  }

  /** Re-construct every existing tab through the kernel — retrofit the
   *  current plugin set onto tabs made before it was installed. */
  remakeAll() {
    this.tabs.value = this.tabs.value.map((tab) => makeTab(tab.title));
  }

  closeTab(tab: TabInstance) {
    this.tabs.value = this.tabs.value.filter((existing) => existing !== tab);
  }
}

export namespace KernelExample {
  export const $Class = $KernelExample; // raw — children `extends` this
  export const Class = Reactive($Class); // reactive — you `new` this
  export type Instance = typeof Class.Instance; // defineExpose type & reactive() interop
}

export const manifest = {
  slug: 'kernel-pattern',
  title: 'Plugin Kernel',
  blurb:
    'Construction binds to a name — plugins extend any class through a 15-line registry.',
  docsPath: '/examples/kernel-pattern',
} as const;

import type { Component } from 'vue';
import { manifest as counter } from './counter/manifest';
import { manifest as derived } from './derived/manifest';
import { manifest as lifecycle } from './lifecycle/manifest';
import { manifest as inheritance } from './inheritance/manifest';
import { manifest as pointer } from './pointer/manifest';
import { manifest as storePattern } from './store-pattern/manifest';
import { manifest as kernelPattern } from './kernel-pattern/manifest';
import { manifest as chooseField } from './fields/choose-field/manifest';
import { manifest as mediaField } from './fields/media-field/manifest';
import { manifest as virtualScroller } from './virtual-scroller/manifest';
import { manifest as formulaGrid } from './formula-grid/manifest';
import { manifest as flyweightGrid } from './flyweight-grid/manifest';
import { manifest as benchmarks } from './benchmarks/manifest';

export interface ExampleEntry {
  slug: string;
  title: string;
  blurb: string;
  docsPath: string;
  load: () => Promise<{ default: Component }>;
}

// Adding an example = one folder with a manifest + one entry here.
