import { Reactive } from './ivue';
type AnyClass = new (...args: any[]) => any;
interface Node { name: string; current: AnyClass; setter: (c: AnyClass) => void; parent?: string; plugins: string[]; }
const nodes = new Map<string, Node>();

export function defineClass(name: string, base: AnyClass, setter: (c: AnyClass) => void, parent?: string) {
  const current = Reactive(base) as AnyClass;
  nodes.set(name, { name, current, setter, parent, plugins: [] });
  setter(current);
}
export function registerClass(name: string, make: (Base: AnyClass) => AnyClass, plugin: string) {
  const n = nodes.get(name)!;
  n.current = Reactive(make(n.current)) as AnyClass;
  n.plugins.push(plugin);
  n.setter(n.current);
}
function topo(): string[] {
  const out: string[] = []; const seen = new Set<string>();
  const visit = (name: string) => {
    if (seen.has(name)) return; seen.add(name);
    const n = nodes.get(name); if (n?.parent) visit(n.parent);
    out.push(name);
  };
  for (const name of nodes.keys()) visit(name);
  return out;
}
export function seal() {
  for (const name of topo()) {
    const n = nodes.get(name)!;
    if (!n.parent) continue;
    const parent = nodes.get(n.parent)!;
    Object.setPrototypeOf(n.current.prototype, parent.current.prototype);
    Object.setPrototypeOf(n.current, parent.current);
    n.current = Reactive(n.current) as AnyClass;
    n.setter(n.current);
  }
}
export function graph() {
  return [...nodes.values()].map(n => ({ name: n.name, parent: n.parent ?? null, plugins: [...n.plugins] }));
}
TS
