async (page) => {
  const errs = [];
  page.on('pageerror', (e) => errs.push((e.message || String(e)).slice(0,200)));
  const out = {};
  await page.goto('about:blank');
  await page.setViewportSize({ width: 1100, height: 900 });
  await page.goto('http://localhost:4221/#/kernel-pattern');
  await page.waitForTimeout(1200);

  const badgesOf = (title) => page.evaluate((t) => {
    const card = [...document.querySelectorAll('.kx-tab')].find(c => c.querySelector('.kx-tab__title')?.textContent === t);
    return card ? [...card.querySelectorAll('.kx-badge')].map(b => b.textContent.trim()) : null;
  }, title);

  out.tabBase = await badgesOf('Tab 1');          // [] base
  out.pinnedBase = await badgesOf('Pinned 2');    // ['pinned'] only

  // enable Timestamp → reseal → BOTH Tab and Pinned rebuild with it
  await page.locator('.kx-plugins .btn', { hasText: 'Timestamp' }).click();
  await page.waitForTimeout(300);
  out.tabTS = await badgesOf('Tab 1');            // ['opened ...']
  out.pinnedTS = await badgesOf('Pinned 2');      // ['pinned','opened ...'] — chain finalized!

  // + Priority → stacking + accent override, pinned inherits both
  await page.locator('.kx-plugins .btn', { hasText: 'Priority' }).click();
  await page.waitForTimeout(300);
  out.tabBoth = await badgesOf('Tab 1');          // ['priority','opened ...']
  out.pinnedBoth = await badgesOf('Pinned 2');    // ['pinned','priority','opened ...']
  out.pinnedAccent = await page.evaluate(() => {
    const card = [...document.querySelectorAll('.kx-tab')].find(c => c.querySelector('.kx-tab__title')?.textContent === 'Pinned 2');
    return getComputedStyle(card).borderLeftColor;
  });

  // the live graph panel
  out.graph = await page.locator('.kx-graph__row').allInnerTexts();

  // toggle Timestamp OFF → reseal removes it everywhere
  await page.locator('.kx-plugins .btn', { hasText: 'Timestamp' }).click();
  await page.waitForTimeout(300);
  out.tabAfterOff = await badgesOf('Tab 1');      // ['priority'] only

  out.errors = errs.slice(0,3);
  return JSON.stringify(out, null, 2);
}

