     in the border box — one element, no wrapper */
  border: 1px solid transparent;
  background:
    linear-gradient(var(--vp-c-bg), var(--vp-c-bg)) padding-box,
    linear-gradient(
        120deg,
        rgba(99, 102, 241, 0.55),
        rgba(45, 212, 191, 0.35) 55%,
        rgba(52, 211, 153, 0.55)
      )
      border-box;
}
.dark .ix .ix-standard-hero {
  background:
    linear-gradient(var(--vp-c-bg-alt), var(--vp-c-bg-alt)) padding-box,
    linear-gradient(
        120deg,
        rgba(129, 140, 248, 0.5),
        rgba(45, 212, 191, 0.28) 55%,
        rgba(52, 211, 153, 0.5)
      )
      border-box;
}
