    radial-gradient(560px 320px at 96% 110%, rgba(52, 211, 153, 0.09), transparent 62%);
}
.dark .ix .ix-standard-hero::before {
  background:
    radial-gradient(620px 320px at 10% -10%, rgba(99, 102, 241, 0.17), transparent 62%),
    radial-gradient(560px 320px at 96% 110%, rgba(52, 211, 153, 0.13), transparent 62%);
}
