  background-size:
    12px 12px,
    cover;
  background-position: center, center;
  background-repeat: no-repeat;
}
/* checked items read as done — dim the line so the open ones stand out */
.vp-doc li.task-item:has(.task-checkbox:checked) {
  color: var(--vp-c-text-3);
  transition: color 0.15s ease;
}

